if (msg.payload.length !== 608) {
     msg = null;
}
return msg;

// gesamt
var P_bez = msg.payload.P_bez;
P_bez = parseInt(P_bez.toFixed(1));
var P_bez2 = parseInt(P_bez.toFixed(0));
var P_ein = msg.payload.P_ein;
P_ein = parseInt(P_ein.toFixed(1));
var P_ein2 = parseInt(P_ein.toFixed(0));
var Q_ind = msg.payload.Q_ind;
var Q_kap = msg.payload.Q_kap;
var Q;
if (Q_ind > 0 && Q_kap == 0) {
    Q = Q_ind * (-1);
} else {
    Q = Q_kap;
}
Q = parseInt(Q.toFixed(0));
var cos_phi = msg.payload.cos_phi;
cos_phi = parseFloat(cos_phi.toFixed(2));
var Hz = msg.payload.Hz;
Hz = parseInt(Hz.toFixed(3));
// L1
var P1_bez = msg.payload.P1_bez;
P1_bez = parseInt(P1_bez.toFixed(1));
var Q1_ind = msg.payload.Q1_ind;
var Q1_kap = msg.payload.Q1_kap;
var Q1;
if (Q1_ind > 0 && Q1_kap == 0) {
    Q1 = Q1_ind *(-1);
} else {
    Q1 = Q1_kap;
}
Q1 = parseInt(Q1.toFixed(0));
var U1 = msg.payload.U1;
U1 = parseInt(U1.toFixed(2));
flow.set("U1",U1);
var cos_phi1 = msg.payload.cos_phi1;
cos_phi1 = parseFloat(cos_phi1.toFixed(2));
// L2
var P2_bez = msg.payload.P2_bez;
P2_bez = parseInt(P2_bez.toFixed(1));
var Q2_ind = msg.payload.Q2_ind;
var Q2_kap = msg.payload.Q2_kap;
var Q2;
if (Q2_ind > 0 && Q2_kap == 0) {
    Q2 = Q2_ind * (-1);
} else {
    Q2 = Q2_kap;
}
Q2 = parseInt(Q2.toFixed(0));
var U2 = msg.payload.U2;
U2 = parseInt(U2.toFixed(2));
flow.set("U2",U2);
var cos_phi2 = msg.payload.cos_phi2;
cos_phi2 = parseFloat(cos_phi2.toFixed(2));
// L3
var P3_bez = msg.payload.P3_bez;
P3_bez = parseInt(P3_bez.toFixed(1));
var Q3_ind = msg.payload.Q3_ind;
var Q3_kap = msg.payload.Q3_kap;
var Q3;
if (Q3_ind > 0 && Q3_kap == 0) {
    Q3 = Q3_ind * -1;
} else {
    Q3 = Q3_kap;
}
Q3 = parseInt(Q3.toFixed(0));
var U3 = msg.payload.U3;
U3 = parseInt(U3.toFixed(2));
flow.set("U3",U3);
var cos_phi3 = msg.payload.cos_phi3;
cos_phi3 = parseFloat(cos_phi3.toFixed(2));
// Ströme mit Vorzeichen
// var I1 = msg.payload.I1;
// var I2 = msg.payload.I2;
// var I3 = msg.payload.I3;
var E1 = msg.payload.P1_ein;
var P1_ein = parseInt(E1.toFixed(1));
var E2 = msg.payload.P2_ein;
var P2_ein = parseInt(E2.toFixed(1));
var E3 = msg.payload.P3_ein;
var P3_ein = parseInt(E3.toFixed(1));
//var I1a;
//var I2a;
//var I3a;
if(E1 > 0 ) {
    //I1a = I1 * (-1);
    P1_bez = -P1_ein;
} else {
    //I1a = I1;
}
if(E2 > 0 ) {
    //I2a = I2 * (-1);
    P2_bez = -P2_ein;
} else {
    //I2a = I2;
}
if(E3 > 0) {
    //I3a = I3 * (-1);
    P3_bez = -P3_ein;
} else {
    //I3a = I3;
}
if (P_ein > 0){
    P_bez = -P_ein;  
}
//var I11 = parseInt(I1a.toFixed(2));
//var I22 = parseInt(I2a.toFixed(2));
//var I33 = parseInt(I3a.toFixed(2));

var I11 = Math.round(P1_bez/U1);
var I22 = Math.round(P2_bez/U1);
var I33 = Math.round(P3_bez/U2);

msg.payload = {P_bez,P_bez2,P_ein,P_ein2,Q,cos_phi,Hz,P1_bez,P1_ein,Q1,I11,U1,cos_phi1,P2_bez,P2_ein,Q2,I22,U2,cos_phi2,P3_bez,P3_ein,Q3,I33,U3,cos_phi3};
msg.topic = "Calculations";

// V3 direct flow-state update for grid values
flow.set("P_Grid", P_bez);
flow.set("P1_Grid", P1_bez);
flow.set("P2_Grid", P2_bez);
flow.set("P3_Grid", P3_bez);
flow.set("I1_Grid", I11);
flow.set("I2_Grid", I22);
flow.set("I3_Grid", I33);
flow.set("V1_Grid", U1);
flow.set("V2_Grid", U2);
flow.set("V3_Grid", U3);
flow.set("Frequency", Hz);
flow.set("CosPhi", cos_phi);
flow.set("CosPhi1", cos_phi1);
flow.set("CosPhi2", cos_phi2);
flow.set("CosPhi3", cos_phi3);

return msg;

function n(v,d=0){
    v = Number(v);
    return isFinite(v) ? v : d;
}
function clamp(v,min,max){ return Math.max(min, Math.min(max,v)); }

let joined = msg.payload || {};
let inv = joined.Inverter || {};
let calc = joined.Calculations || {};
let stor = joined.Storage || {};

let I1_PV = n(inv.I_generate_by_PV_I1, n(flow.get("I1_PV")));
let I2_PV = n(inv.I_generate_by_PV_I2, n(flow.get("I2_PV")));
let I3_PV = n(inv.I_generate_by_PV_I3, n(flow.get("I3_PV")));
let I1_Grid = n(calc.I11, n(flow.get("I1_Grid")));
let I2_Grid = n(calc.I22, n(flow.get("I2_Grid")));
let I3_Grid = n(calc.I33, n(flow.get("I3_Grid")));
let I1_Batt = n(stor.I_net_batt_charge, n(flow.get("I1_Batt")));
let I2_Batt = 0;
let I3_Batt = 0;

let P_PV = n(inv.P_generate_by_PV, n(flow.get("P_PV")));
let P1_PV = n(inv.P_generate_by_PV_L1, n(flow.get("P1_PV")));
let P2_PV = n(inv.P_generate_by_PV_L2, n(flow.get("P2_PV")));
let P3_PV = n(inv.P_generate_by_PV_L3, n(flow.get("P3_PV")));
let P_Grid = n(calc.P_bez, n(flow.get("P_Grid")));
let P1_Grid = n(calc.P1_bez, n(flow.get("P1_Grid")));
let P2_Grid = n(calc.P2_bez, n(flow.get("P2_Grid")));
let P3_Grid = n(calc.P3_bez, n(flow.get("P3_Grid")));

// User convention:
//   P_Batt > 0 = battery discharge to home
//   P_Batt < 0 = battery charging
let P_Batt = n(stor.P_net_batt_charge, n(flow.get("P_Batt")));
let P1_Batt = n(stor.P1_net_batt_charge, n(flow.get("P1_Batt"), P_Batt));
let P2_Batt = 0;
let P3_Batt = 0;

// Dropout protection for battery values.
let lastBatt = n(flow.get("P_Batt_last_nonzero"), 0);
let lastBattSeen = n(flow.get("P_Batt_last_nonzero_seen"), 0);
let lastBattRecent = (Date.now() - lastBattSeen) < 120000;
if (Math.abs(P_Batt) > 250) {
    flow.set("P_Batt_last_nonzero", P_Batt);
    flow.set("P_Batt_last_nonzero_seen", Date.now());
}
if (Math.abs(P_PV) < 250 && Math.abs(P_Grid) < 250 && Math.abs(P_Batt) < 250 && Math.abs(lastBatt) > 500 && lastBattRecent) {
    P_Batt = lastBatt;
    P1_Batt = lastBatt;
    I1_Batt = n(flow.get("I1_Batt"), Math.round((P_Batt / 230) * 10) / 10);
}

// This is the total load seen by SMA/Home Manager. It includes the EV when charging.
let P_Total_Load = P_PV + P_Grid + P_Batt;
let P1_Total_Load = P1_PV + P1_Grid + P1_Batt;
let P2_Total_Load = P2_PV + P2_Grid + P2_Batt;
let P3_Total_Load = P3_PV + P3_Grid + P3_Batt;

let evConnected = flow.get("EV_Connected") === true;
let evTargetW = n(flow.get("ems_ev_kw_target"), 0) * 1000;
let evPossiblyCharging = evConnected && evTargetW > 300;

// IMPORTANT FIX:
// Do NOT simply set EV power equal to the EMS target. The charger ramps slowly and the
// target can be higher than the measured total load, which made Home become 0 W.
// Without a reliable actual Alfen power register in this flow, estimate EV from the
// increase above a house-only baseline measured while the EV was not actively charging.
let baseline = n(flow.get("P_Home_Baseline_No_EV"), 0);
let baselineSeen = n(flow.get("P_Home_Baseline_No_EV_seen"), 0);
let baselineRecent = (Date.now() - baselineSeen) < 6 * 3600000;

// Update baseline only when EV target is off/low. Use realistic house values only.
if (!evPossiblyCharging && P_Total_Load > 250 && P_Total_Load < 8000) {
    let prev = baseline || P_Total_Load;
    baseline = Math.round(prev * 0.85 + P_Total_Load * 0.15);
    flow.set("P_Home_Baseline_No_EV", baseline);
    flow.set("P_Home_Baseline_No_EV_seen", Date.now());
    baselineRecent = true;
}

// Fallback baseline if EV is already charging and no baseline is known.
if (!baselineRecent || baseline < 250) {
    baseline = n(flow.get("P_Home_Consumption_last_valid"), 900);
    if (baseline < 250) baseline = 900;
}

let P_EV = 0;
if (evPossiblyCharging) {
    P_EV = clamp(P_Total_Load - baseline, 0, evTargetW > 0 ? evTargetW * 1.10 : 11000);
    // If the total load is below the baseline, the EV is effectively not drawing yet.
    if (P_Total_Load < baseline + 250) P_EV = 0;
}
flow.set("Actual_P_EV", P_EV);
flow.set("Actual_P_EV_estimated", evPossiblyCharging && P_EV > 0);

let P_Home_Consumption = Math.max(0, P_Total_Load - P_EV);
let P_EV_phase = P_EV / 3;
let P1_Home_Consumption = Math.max(0, P1_Total_Load - P_EV_phase);
let P2_Home_Consumption = Math.max(0, P2_Total_Load - P_EV_phase);
let P3_Home_Consumption = Math.max(0, P3_Total_Load - P_EV_phase);

// Plausibility hold: keep last realistic home value briefly if a measurement dropout occurs.
let lastHome = n(flow.get("P_Home_Consumption_last_valid"), 0);
let lastHomeSeen = n(flow.get("P_Home_Consumption_last_valid_seen"), 0);
let lastHomeRecent = (Date.now() - lastHomeSeen) < 120000;
if (P_Home_Consumption < 250 && lastHome > 600 && lastHomeRecent && !evPossiblyCharging) {
    P_Home_Consumption = lastHome;
}
if (P_Home_Consumption > 300) {
    flow.set("P_Home_Consumption_last_valid", P_Home_Consumption);
    flow.set("P_Home_Consumption_last_valid_seen", Date.now());
}

// Short moving average to avoid spikes/dropouts in the dashboard before the EMS decision engine refreshes.
let homeHist = flow.get("P_Home_Consumption_hist_pre") || [];
if (!Array.isArray(homeHist)) homeHist = [];
homeHist.push(P_Home_Consumption);
while (homeHist.length > 4) homeHist.shift();
flow.set("P_Home_Consumption_hist_pre", homeHist);
P_Home_Consumption = Math.round(homeHist.reduce((a,b)=>a+b,0) / homeHist.length);

let I_EV_phase = P_EV > 0 ? P_EV / (Math.sqrt(3) * 400) : 0;
let I1_Home_Consumption = Math.max(0, I1_PV + I1_Grid + I1_Batt - I_EV_phase);
let I2_Home_Consumption = Math.max(0, I2_PV + I2_Grid + I2_Batt - I_EV_phase);
let I3_Home_Consumption = Math.max(0, I3_PV + I3_Grid + I3_Batt - I_EV_phase);

flow.set("I1_Home", I1_Home_Consumption);
flow.set("I2_Home", I2_Home_Consumption);
flow.set("I3_Home", I3_Home_Consumption);
flow.set("I1_Home_Consumption", I1_Home_Consumption);
flow.set("I2_Home_Consumption", I2_Home_Consumption);
flow.set("I3_Home_Consumption", I3_Home_Consumption);
flow.set("P_Home_Consumption", P_Home_Consumption);
flow.set("P1_Home_Consumption", P1_Home_Consumption);
flow.set("P2_Home_Consumption", P2_Home_Consumption);
flow.set("P3_Home_Consumption", P3_Home_Consumption);
flow.set("P_Total_Load_Including_EV", P_Total_Load);
flow.set("P_Grid", P_Grid);
flow.set("P_PV", P_PV);
flow.set("P_Batt", P_Batt);

msg.payload = {
    P_Grid,
    P_PV,
    P_Batt,
    P_EV,
    P_Total_Load_Including_EV: P_Total_Load,
    P_Home_Consumption,
    P1_Home_Consumption,
    P2_Home_Consumption,
    P3_Home_Consumption,
    I1_Home_Consumption,
    I2_Home_Consumption,
    I3_Home_Consumption
};
return msg;

// Build three Energy-Charts URLs: yesterday, today, tomorrow.
// IMPORTANT: Energy-Charts uses an interval; end must be the NEXT day.
// Using start=end can return an empty dataset, which leaves the chart with only axes.
const country = "BE";
function isoDate(offsetDays){
    let d = new Date();
    const tz = d.getTimezoneOffset();
    d = new Date(d.getTime() - tz*60000 + offsetDays*24*3600000);
    return d.toISOString().split('T')[0];
}
let days = [
    {key:'yesterday', offset:-1},
    {key:'today', offset:0},
    {key:'tomorrow', offset:1}
];
return days.map(d => {
    let start = isoDate(d.offset);
    let end = isoDate(d.offset + 1);
    return {
        dayKey: d.key,
        url: `https://api.energy-charts.info/price?bzn=${country}&start=${start}&end=${end}`,
        payload: null
    };
});

// Parse Energy-Charts data and build 96 quarter-hour price arrays.
// If today's/yesterday's response fails: keep previous good data.
// If tomorrow's response fails: clear tomorrow arrays, because prices may not be available yet.

let dayKey = msg.dayKey || msg.topic;

let data = msg.payload;

function clearTomorrow(reason) {
    if (dayKey === 'tomorrow') {
        flow.set('day_ahead_price_array', []);
        flow.set('day_ahead_price_array_injectie', []);
        flow.set('day_ahead_price_available', false);
        node.warn('Tomorrow prices not available. Cleared day_ahead arrays. Reason: ' + reason);
    }
}

if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.warn('Energy-Charts JSON parse error for ' + dayKey + '. Payload: ' + data.slice(0,120));
        clearTomorrow('JSON parse error');
        return null;
    }
}

if (!data || typeof data !== 'object') {
    node.warn('Energy-Charts invalid response for ' + dayKey + '.');
    clearTomorrow('invalid response');
    return null;
}

let raw = [];

if (Array.isArray(data.price)) raw = data.price;
else if (Array.isArray(data.data)) raw = data.data;
else if (Array.isArray(data.values)) raw = data.values;
else if (Array.isArray(data)) raw = data;

let arr = raw.map(v => {
    if (typeof v === 'number') return v;
    if (Array.isArray(v)) return Number(v[1] ?? v[0]);
    if (v && typeof v === 'object') return Number(v.price ?? v.value ?? v.y);
    return Number(v);
}).filter(v => isFinite(v));

let quarters = [];

if (arr.length >= 96) {
    quarters = arr.slice(0, 96);
} else if (arr.length >= 24) {
    for (let i = 0; i < 24; i++) {
        for (let q = 0; q < 4; q++) {
            quarters.push(arr[i]);
        }
    }
}

if (quarters.length < 24) {
    node.warn('Energy-Charts response has too few price values for ' + dayKey + ': ' + quarters.length);
    clearTomorrow('too few price values');
    return null;
}

let priceArray_injectie = [];
let priceArray_afname = [];

let VAT = 0.06;
let distributietarief = 0.17510;

for (let i = 0; i < 96; i++) {
    let eSpot = Number(quarters[i]);

    if (!isFinite(eSpot)) {
        eSpot = Number(quarters[quarters.length - 1]) || 0;
    }

    priceArray_afname[i] =
        Math.round((eSpot * 0.1019 + 1.3163 + distributietarief + Number.EPSILON) * (1 + VAT) * 100) / 100;

    priceArray_injectie[i] =
        Math.round((eSpot * 0.1000 - 1.3050 + distributietarief + Number.EPSILON) * 100) / 100;
}

function allZero(a) {
    return a.every(v => Number(v) === 0);
}

if (allZero(priceArray_afname) && allZero(priceArray_injectie)) {
    node.warn('Energy-Charts produced all-zero prices for ' + dayKey + '.');
    clearTomorrow('all-zero prices');
    return null;
}

node.warn({
    dayKey,
    url: msg.url || msg.topic,
    first: priceArray_afname[0],
    last: priceArray_afname[95]
});

node.warn('STORING AS: ' + dayKey);

if (dayKey === 'yesterday') {
    flow.set('day_previous_price_array', priceArray_afname);
    flow.set('day_previous_price_array_injectie', priceArray_injectie);
}

if (dayKey === 'today') {
    flow.set('day_price_array', priceArray_afname);
    flow.set('day_price_array_injectie', priceArray_injectie);
}

if (dayKey === 'tomorrow') {
    flow.set('day_ahead_price_array', priceArray_afname);
    flow.set('day_ahead_price_array_injectie', priceArray_injectie);
    flow.set('day_ahead_price_available', true);
}

flow.set('price_last_success_ts', Date.now());

msg.payload = {
    dayKey,
    points: quarters.length,
    afname: priceArray_afname,
    injectie: priceArray_injectie,
    tomorrowAvailable: flow.get('day_ahead_price_available') || false
};

return msg;

function validArray(a){
    if (!Array.isArray(a) || a.length < 96) return false;
    let nums = a.map(Number).filter(v => isFinite(v));
    if (nums.length < 80) return false;
    if (nums.every(v => v === 0)) return false;
    return true;
}
let buyArr = flow.get('day_price_array');
let sellArr = flow.get('day_price_array_injectie');
let valid = validArray(buyArr) && validArray(sellArr);
let now = new Date();
let idx = now.getHours()*4 + Math.floor(now.getMinutes()/15);
let buy = valid ? Number(buyArr[idx]) : null;
let sell = valid ? Number(sellArr[idx]) : null;
flow.set('price_data_valid', valid);
flow.set('current_quarter_price', buy);
flow.set('current_quarter_injectie_price', sell);
msg.payload = {
    valid,
    buy,
    sell,
    index: idx,
    buyText: valid ? buy.toFixed(2) : '--',
    sellText: valid ? sell.toFixed(2) : '--',
    buyColor: valid && buy < 0 ? 'green' : 'black',
    sellColor: valid && sell < 0 ? 'red' : 'black',
    warning: valid ? '' : 'PRICE DATA INVALID - Summer/Winter suspended'
};
return [msg, {payload:msg.payload}];

let s = flow.get('ems_settings') || {
    ems_mode:'SMA',
    battery_mode:'AUTO',
    solar_mode:'AUTO',
    solar_kw:10,
    ev_enabled:false,
    ev_manual:false,
    ev_manual_kw:4,
    ev_timer:false,
    ev_timer_kw:4,
    ev_timer_minutes:60,
    ev_timer_schedule_active:false,
    ev_solar:false,
    winter_threshold:0,
    winter_ev_kw:6
};

let p = msg.payload;
let evConnected = flow.get('EV_Connected') === true;

// Refresh trigger from EV State listing / periodic dashboard refresh.
// This must not be ignored, otherwise the EV dashboard keeps the old disabled state.
if (p === 'refresh_ev_ui' || msg.topic === 'ev_state_refresh') {
    if (evConnected) {
        s.ev_enabled = true;
    } else {
        s.ev_enabled = false;
        s.ev_manual = false;
        s.ev_timer = false;
        s.ev_solar = false;
    }
}
else if (typeof p === 'string') {
    if (p.startsWith('EMS_MODE:')) {
        s.ems_mode = p.split(':')[1];
        s.battery_mode = 'AUTO';
        s.solar_mode = 'AUTO';
    }
    else if (p.startsWith('BATTERY_MODE:')) {
        s.battery_mode = p.split(':')[1];
    }
    else if (p.startsWith('SOLAR_MODE:')) {
        s.solar_mode = p.split(':')[1];
    }
}
else if (msg.topic === 'solar_kw') {
    s.solar_kw = Number(p);
}
else if (msg.topic === 'ev_enable') {
    // EV enable is automatic: ON whenever the car is connected, OFF when disconnected.
    // Ignore dashboard attempts to switch it off while connected; it is a status/master indicator.
    s.ev_enabled = evConnected;
    if (!evConnected) {
        s.ev_manual = false;
        s.ev_timer = false;
        s.ev_solar = false;
    }
}
else if (msg.topic === 'ev_manual') {
    s.ev_manual = evConnected && s.ev_enabled && !!p;
}
else if (msg.topic === 'ev_manual_kw') {
    s.ev_manual_kw = Number(p);
}
else if (msg.topic === 'ev_timer') {
    s.ev_timer = evConnected && s.ev_enabled && !!p;
    if (s.ev_timer) {
        s.ev_timer_until = Date.now() + (Number(s.ev_timer_minutes || 60) * 60000);
    }
}
else if (msg.topic === 'ev_timer_kw') {
    s.ev_timer_kw = Number(p);
}
else if (msg.topic === 'ev_timer_minutes') {
    s.ev_timer_minutes = Number(p);
}
else if (msg.topic === 'ev_timer_schedule_active') {
    // Updated by the weekly EV scheduler widget. The Timer EV switch remains the master enable.
    s.ev_timer_schedule_active = !!p;
    flow.set('EV_timer_scheduler_active', !!p);
}
else if (msg.topic === 'ev_solar') {
    s.ev_solar = evConnected && s.ev_enabled && !!p;
    if (s.ev_solar) {
        s.solar_mode = 'AUTO';
    }
}
else if (msg.topic === 'winter_threshold') {
    s.winter_threshold = Number(p);
}
else if (msg.topic === 'winter_ev_kw') {
    s.winter_ev_kw = Number(p);
}

// Hard rule: Enable charging follows the EV connection state.
// Connected => enabled always ON. Disconnected => everything EV-related OFF.
if (evConnected) {
    s.ev_enabled = true;
} else {
    s.ev_enabled = false;
    s.ev_manual = false;
    s.ev_timer = false;
    s.ev_solar = false;
    flow.set('ems_ev_kw_target', 0);
    flow.set('ems_ev_a_target', 0);
}

flow.set('ems_settings', s);

// Output 1 saves settings. Output 2 refreshes the dashboard state buttons/switches.
return [
    { payload: JSON.stringify(s) },
    { payload: s }
];

msg.payload = { 
    'fc': 3, 
    'unitid': 1, 
    'address': 1201 , 
    'quantity': 5 } 
return msg

function regToAscii(reg) {
    reg = Number(reg);
    if (!isFinite(reg)) return "";
    let hi = (reg >> 8) & 0xFF;
    let lo = reg & 0xFF;
    let s = "";
    if (hi >= 32 && hi <= 126) s += String.fromCharCode(hi);
    if (lo >= 32 && lo <= 126) s += String.fromCharCode(lo);
    return s;
}

let b1 = msg.payload?.Byte1;
let b2 = msg.payload?.Byte2;
let EV_State = "";

if (b1 !== undefined || b2 !== undefined) {
    EV_State = String(b1 || "") + String(b2 || "");
} else if (Array.isArray(msg.payload?.data)) {
    // modbus-flex-getter normally returns registers in msg.payload.data
    // State can be returned as ASCII packed in one register, e.g. 0x4231 = "B1".
    let regs = msg.payload.data;
    EV_State = regs.map(regToAscii).join("").replace(/\u0000/g, "").trim();
} else if (Array.isArray(msg.payload)) {
    EV_State = msg.payload.map(regToAscii).join("").replace(/\u0000/g, "").trim();
} else if (Buffer.isBuffer(msg.responseBuffer?.buffer)) {
    EV_State = msg.responseBuffer.buffer.toString("ascii").replace(/\u0000/g, "").trim();
} else if (Buffer.isBuffer(msg.payload?.buffer)) {
    EV_State = msg.payload.buffer.toString("ascii").replace(/\u0000/g, "").trim();
}

// Keep only the known Alfen state codes if the string contains more data.
let match = EV_State.match(/(A|B1|B2|C1|C2|D1|D2|E|F)/);
let parsedOk = !!match;
EV_State = parsedOk ? match[1] : EV_State;

// IMPORTANT:
// If the Modbus state cannot be decoded, do NOT overwrite EV_Connected with false.
// That was causing the dashboard to disable charging after redeploy/startup even when the car was connected.
let previousConnected = flow.get("EV_Connected");
let connected = previousConnected === undefined ? false : previousConnected === true;
let charging = flow.get("EV_Charging") === true;
let ready = flow.get("EV_Ready") || "OK";

if (parsedOk) {
    connected = ["B1", "B2", "C1", "C2", "D1", "D2"].includes(EV_State);
    charging  = ["C2", "D2"].includes(EV_State);
    ready     = (EV_State === "F") ? "Error" : "OK";
    flow.set("EV_State", EV_State);
    flow.set("EV_Connected", connected);
    flow.set("EV_Charging", charging);
    flow.set("EV_Ready", ready);
} else {
    flow.set("EV_State_Raw_Last", EV_State);
}

if (connected) flow.set("EV_ever_connected", true);

// Also update ems_settings immediately so the dashboard switch follows the car state.
let s = flow.get("ems_settings") || {
    ems_mode:"SMA", battery_mode:"AUTO", solar_mode:"AUTO", solar_kw:10,
    ev_enabled:false, ev_manual:false, ev_manual_kw:4, ev_timer:false, ev_timer_kw:4, ev_timer_minutes:60,
    ev_solar:false, winter_threshold:0, winter_ev_kw:6
};

if (connected) {
    s.ev_enabled = true;
} else {
    s.ev_enabled = false;
    s.ev_manual = false;
    s.ev_timer = false;
    s.ev_solar = false;
    flow.set("ems_ev_kw_target", 0);
    flow.set("ems_ev_a_target", 0);
}
flow.set("ems_settings", s);

let msg1 = {
    payload: connected ? "CONNECTED" : "NOT CONNECTED",
    color: connected ? "green" : "black"
};
if (ready === "Error") msg1 = {payload:"ERROR", color:"red"};

let msg2 = {payload: charging ? "CHARGING" : "NOT CHARGING"};

let msg_refresh = {
    payload: "refresh_ev_ui",
    topic: "ev_state_refresh",
    EV_State,
    EV_Connected: connected,
    EV_Charging: charging
};

return [msg1, msg2, msg_refresh, msg_refresh];

let currentA = Number(msg.payload);
if (!isFinite(currentA)) return null;

flow.set("diag_alfen_write_ts", Date.now());
flow.set("diag_alfen_write_value", currentA);

msg.payload = { 
    value: msg.payload,
    fc: 16, 
    unitid: 1, 
