return msg;

const float = msg.payload;
const buffer = new ArrayBuffer(4);
const view = new DataView(buffer);
view.setFloat32(0, float); // Default is big endian

// Extract 2 x 16-bit integers (registers)
const reg1 = view.getUint16(0); // High
const reg2 = view.getUint16(2); // Low

msg.payload = [reg1, reg2]; // Two 16-bit values
return msg;

const UNIT_ID = 3;
const SMA_REGISTER = 40023;
const ZERO_BASED_ADDRESSING = false;

// Slider now gives kW (0–10)
let kw = Number(msg.payload);

if (isNaN(kw)) {
    node.error("Slider value is not a number", msg);
    return null;
}

// Clamp between 0 and 10 kW
if (kw < 0) kw = 0;
if (kw > 10) kw = 10;

// Convert kW → %
let percent = (kw / 10) * 100;

// Convert % → SMA value (*100)
const registerValue = Math.round(percent * 100);

const address = ZERO_BASED_ADDRESSING ? SMA_REGISTER - 1 : SMA_REGISTER;

msg.payload = {
    value: registerValue,
    fc: 6,
    unitid: UNIT_ID,
    address: address,
    quantity: 1
};

// Nice readable info
msg.topic = `Set SMA max output to ${kw} kW`;
msg.sma_limit_kw = kw;
msg.sma_limit_percent = percent;
msg.sma_register_value = registerValue;
flow.set("diag_pv_write_ts", Date.now());
flow.set("diag_pv_write_value", registerValue);
flow.set("diag_pv_write_kw", kw);

return msg;

function n(v,d=0){ v=Number(v); return isFinite(v)?v:d; }
function clamp(v,min,max){ return Math.max(min, Math.min(max,v)); }
function validArray(a){ if(!Array.isArray(a)||a.length<96) return false; let nums=a.map(Number).filter(isFinite); return nums.length>=80 && !nums.every(v=>v===0); }

// ---- TUNING SETTINGS ----
const HOME_AVG_N = 3;
const GRID_AVG_N = 2;
const BATT_AVG_N = 2;

const EV_MIN_KW = 4.2;
const EV_MAX_KW = 11;
const GRID_TARGET_W = 800;
const GRID_DEADBAND_W = 250;
const SOLAR_STEP_KW = 1.0;

const SOLAR_PROBE_INTERVAL_MS = 30 * 60 * 1000;
const SOLAR_PROBE_DURATION_MS = 5 * 60 * 1000;
const EV_SUCCESS_W = 4000;
const EV_SUCCESS_DURATION_MS = 2 * 60 * 1000;
// -------------------------

let s = flow.get('ems_settings') || {
    ems_mode:'SMA',
    battery_mode:'AUTO',
    solar_mode:'AUTO',
    solar_kw:10,
