// In SUMMER mode, Solar control must always be AUTO.
if (s.ems_mode === 'SUMMER') {
    s.solar_mode = 'AUTO';
}

let now = Date.now();
let todayKey = new Date().toISOString().slice(0,10);

if (flow.get('EV_solar_charge_success_day') !== todayKey) {
    flow.set('EV_solar_charge_success_today', false);
    flow.set('EV_solar_charge_success_day', todayKey);
