let P_Grid=n(flow.get('P_Grid')), P_PV=n(flow.get('P_PV')), P_Batt=n(flow.get('P_Batt')), SOC=n(flow.get('Battery_Soc'));
let P_Total_Load = P_PV + P_Grid + P_Batt;

let alfenPowerAge = now - n(flow.get('alfen_actual_power_last_good'),0);
let alfenCurrentAge = now - n(flow.get('alfen_actual_current_last_good'),0);
let alfenFresh = alfenPowerAge < 20000 || alfenCurrentAge < 20000;

let Actual_P_EV = connected && alfenFresh ? Math.max(0, n(flow.get('Actual_P_EV'))) : 0;
let Actual_I1_EV = connected && alfenCurrentAge < 20000 ? n(flow.get('Actual_I1_EV')) : 0;
let Actual_I2_EV = connected && alfenCurrentAge < 20000 ? n(flow.get('Actual_I2_EV')) : 0;
let Actual_I3_EV = connected && alfenCurrentAge < 20000 ? n(flow.get('Actual_I3_EV')) : 0;

flow.set('Actual_P_EV', Actual_P_EV);
flow.set('Actual_P_EV_estimated', false);

let P_Home_raw = Math.max(0, P_Total_Load - Actual_P_EV);

function movingAvg(key, value, maxLen){
    value = n(value, null);
    if (value === null || !isFinite(value)) return n(flow.get(key + '_avg'), 0);
    let arr = flow.get(key + '_hist') || [];
    if (!Array.isArray(arr)) arr = [];
    arr.push(value);
    while (arr.length > maxLen) arr.shift();
    flow.set(key + '_hist', arr);
    let avg = arr.reduce((a,b)=>a+b,0) / arr.length;
    flow.set(key + '_avg', avg);
    return avg;
}

let P_Home = Math.round(movingAvg('P_Home_Consumption', P_Home_raw, HOME_AVG_N));
let P_Grid_ctrl = Math.round(movingAvg('P_Grid_ctrl', P_Grid, GRID_AVG_N));
let P_Batt_ctrl = Math.round(movingAvg('P_Batt_ctrl', P_Batt, BATT_AVG_N));

let I1=n(flow.get('I1_PV')) + n(flow.get('I1_Grid')) + n(flow.get('I1_Batt'));
let I2=n(flow.get('I2_PV')) + n(flow.get('I2_Grid')) + n(flow.get('I2_Batt'));
let I3=n(flow.get('I3_PV')) + n(flow.get('I3_Grid')) + n(flow.get('I3_Batt'));

