let todayBuy=flow.get('day_price_array'), todaySell=flow.get('day_price_array_injectie');
let priceValid=validArray(todayBuy)&&validArray(todaySell);
flow.set('price_data_valid', priceValid);

let q=new Date().getHours()*4+Math.floor(new Date().getMinutes()/15);
let buy=priceValid?Number(todayBuy[q]):null;
let sell=priceValid?Number(todaySell[q]):null;

let safety=false, reason=[];
let evKwReq=0;

let prevSolarKw = n(flow.get('ems_solar_target_kw'), n(s.solar_kw,10));

let exportW = Math.max(0, -P_Grid_ctrl);
let batteryChargingW = Math.max(0, -P_Batt_ctrl);
let availableSolarForEV = Math.max(0, Actual_P_EV + exportW + batteryChargingW - GRID_TARGET_W);

// Mark EV solar success if actual charging > 4kW for 2 minutes.
let successStart = n(flow.get('EV_success_timer_start'),0);
if (connected && s.ev_enabled && Actual_P_EV > EV_SUCCESS_W) {
    if (!successStart) flow.set('EV_success_timer_start', now);
    else if (now - successStart > EV_SUCCESS_DURATION_MS) {
        flow.set('EV_solar_charge_success_today', true);
        flow.set('EV_solar_charge_success_day', todayKey);
    }
} else {
    flow.set('EV_success_timer_start', 0);
}

let evSuccessToday = flow.get('EV_solar_charge_success_today') === true;

// Solar probe logic
let probeActive = flow.get('solar_probe_active') === true;
let probeStart = n(flow.get('solar_probe_start_ms'),0);
let probeLast = n(flow.get('solar_probe_last_ms'),0);
let probeAge = probeActive ? now - probeStart : 0;

let probeAllowed =
    priceValid &&
    buy >= 0 &&
    s.solar_mode === 'AUTO' &&
    (
        SOC < 99.5 ||
        (connected && s.ev_enabled && s.ev_solar && !evSuccessToday)
    );

if (!probeAllowed) {
    probeActive = false;
    flow.set('solar_probe_active', false);
}

if (!probeActive && probeAllowed && (now - probeLast > SOLAR_PROBE_INTERVAL_MS)) {
    probeActive = true;
    probeStart = now;
    probeAge = 0;
    flow.set('solar_probe_active', true);
    flow.set('solar_probe_start_ms', probeStart);
    flow.set('solar_probe_last_ms', now);
}

let probeInWarmup = probeActive && probeAge < SOLAR_PROBE_DURATION_MS;
let probeReady = probeActive && probeAge >= SOLAR_PROBE_DURATION_MS;

if (probeReady) {
    flow.set('solar_probe_active', false);
    probeActive = false;
}

let manualKw = (s.ev_enabled && connected && s.ev_manual) ? n(s.ev_manual_kw) : 0;
if (manualKw > 0 && manualKw < EV_MIN_KW) manualKw = EV_MIN_KW;

let schedulerActive = (flow.get('EV_timer_scheduler_active') === true) || (s.ev_timer_schedule_active === true);
let timerKw = (s.ev_enabled && connected && s.ev_timer && schedulerActive) ? n(s.ev_timer_kw) : 0;
if (timerKw > 0 && timerKw < EV_MIN_KW) timerKw = EV_MIN_KW;

let hasManualOrTimer = manualKw > 0 || timerKw > 0;

if (s.ev_enabled && connected) {
    evKwReq = Math.max(evKwReq, manualKw, timerKw);

    if (s.ev_solar) {
        if (probeInWarmup && !hasManualOrTimer && Actual_P_EV < 100) {
            if (availableSolarForEV >= EV_MIN_KW * 1000) {
                evKwReq = Math.max(evKwReq, clamp(availableSolarForEV / 1000, EV_MIN_KW, EV_MAX_KW));
                reason.push('Solar check: enough surplus, start EV');
            } else {
                evKwReq = 0;
                reason.push('Solar check active');
            }
        } else if (availableSolarForEV >= EV_MIN_KW * 1000) {
            evKwReq = Math.max(evKwReq, clamp(availableSolarForEV / 1000, EV_MIN_KW, EV_MAX_KW));
        } else if (!hasManualOrTimer) {
            evKwReq = 0;
        }
    }

    if (!(s.ev_solar && !hasManualOrTimer)) {
        if (s.ems_mode==='WINTER' && priceValid && buy < n(s.winter_threshold)) {
            evKwReq=Math.max(evKwReq, Math.max(EV_MIN_KW,n(s.winter_ev_kw)));
        }
        if (s.ems_mode==='SUMMER' && priceValid && buy < 0) {
            evKwReq=Math.max(evKwReq,EV_MAX_KW);
        }
    }
} else {
    evKwReq = 0;
}

evKwReq=clamp(evKwReq,0,EV_MAX_KW);
if (evKwReq > 0 && evKwReq < EV_MIN_KW) evKwReq = EV_MIN_KW;

let maxI=Math.max(I1,I2,I3);
if (maxI>35) { evKwReq=Math.max(0, evKwReq-1); safety=true; reason.push('EV reduced >35A'); }
if (maxI>38) { evKwReq=0; safety=true; reason.push('EV stopped >38A'); }
if (evKwReq > 0 && evKwReq < EV_MIN_KW) evKwReq = 0;

// Battery decision
let battMode=s.battery_mode;
let battW=0;
let battControl='AUTO';

if (battMode==='CHARGE') {
    battControl='CHARGE'; battW=-5000;
} else if (battMode==='HOLD') {
    battControl='HOLD'; battW=0;
} else {
    if (s.ems_mode==='SUMMER' && priceValid && sell<0 && SOC < 99.5) {
        battControl='CHARGE'; battW=-5000;
    } else if (s.ems_mode==='SUMMER' && priceValid && sell<0) {
        battControl='HOLD'; battW=0;
    } else if (s.ems_mode==='SUMMER' && priceValid && buy<0) {
        battControl='CHARGE'; battW=-5000;
    } else if (Actual_P_EV>100 || evKwReq>0) {
        battControl='HOLD'; battW=0;
    } else {
        battControl='AUTO'; battW=0;
    }
}

// Solar decision
// Solar decision
let solarKw = 10;

if (s.ems_mode === 'SUMMER') {
    s.solar_mode = 'AUTO';
}

if (s.solar_mode === 'MANUAL') {
    solarKw = clamp(n(s.solar_kw,10),0,10);
}
else {
    // 1. EV solar charging active: never cap PV.
    // EV current regulates import/export.
    if (connected && s.ev_enabled && s.ev_solar) {
        solarKw = 10;
        reason.push('Solar EV active: PV forced to max');
    }

    // 2. Solar probe active: force PV open.
    else if (probeActive) {
        solarKw = 10;
        reason.push('Solar probe active');
    }

    // 3. Battery not full: allow PV to charge battery.
    else if (SOC < 95 && !(s.ems_mode === 'SUMMER' && priceValid && sell < 0)) {
    solarKw = 10;
    reason.push('Battery below 95%: PV forced to max');
}

    // 4. Normal Summer negative injection logic:
    // NEVER go below home consumption + 0.8kW buffer.
    else if (s.ems_mode === 'SUMMER' && priceValid && sell < 0) {
        let minimumSolarKw = clamp((P_Home + 800) / 1000, 0.5, 10);

        let gridError = GRID_TARGET_W - P_Grid_ctrl;
        solarKw = prevSolarKw;

        if (Math.abs(gridError) > GRID_DEADBAND_W) {
            let step = clamp(Math.abs(gridError) / 1000, 0.2, SOLAR_STEP_KW);
            solarKw += (gridError > 0) ? -step : step;
        }

        // Critical safety floor: do not shut solar below home + 800W.
        solarKw = Math.max(solarKw, minimumSolarKw);
        solarKw = clamp(solarKw, 0.5, 10);

        reason.push('Negative injection: solar limited but home covered');
    }

    // 5. All other cases: full solar.
    else {
        solarKw = 10;
    }
}



