const POINTS_PER_DAY = 96;
const TOTAL_POINTS = POINTS_PER_DAY * 3;

let data_yesterday = flow.get("day_previous_price_array") || [];
let data_today = flow.get("day_price_array") || [];
let data_tomorrow = flow.get("day_ahead_price_array") || [];

let data_yesterday_injectie = flow.get("day_previous_price_array_injectie") || [];
let data_today_injectie = flow.get("day_price_array_injectie") || [];
let data_tomorrow_injectie = flow.get("day_ahead_price_array_injectie") || [];

let input = {
    series: [
        "Gisteren", "Vandaag", "Morgen",
        "Gisteren Injectie", "Vandaag Injectie", "Morgen Injectie"
    ],
    data: []
};

function emptySeries() {
    let a = [];
    for (let i = 0; i < TOTAL_POINTS; i++) a.push({ x: i, y: null });
    return a;
}
function fill(arr, offset) {
    let s = emptySeries();
    for (let i = 0; i < Math.min(arr.length, POINTS_PER_DAY); i++) s[i + offset].y = Number(arr[i]);
    return s;
}

input.data.push(fill(data_yesterday, 0));
input.data.push(fill(data_today, POINTS_PER_DAY));
input.data.push(fill(data_tomorrow, POINTS_PER_DAY * 2));
input.data.push(fill(data_yesterday_injectie, 0));
input.data.push(fill(data_today_injectie, POINTS_PER_DAY));
input.data.push(fill(data_tomorrow_injectie, POINTS_PER_DAY * 2));

let labels = Array.from({ length: TOTAL_POINTS }, (_, i) => {
    const quarter = i % POINTS_PER_DAY;
    const hour = Math.floor(quarter / 4);
    return (quarter % 12 === 0) ? (hour + "h") : "";
});

let datasets = [];
const colors = [
    "rgba(255, 99, 132, 1)",
    "rgba(54, 162, 235, 1)",
    "rgba(75, 192, 192, 1)"
];

for (let i = 0; i < input.series.length; i++) {
    let now = new Date();
    let currentQuarter = now.getHours() * 4 + Math.floor(now.getMinutes() / 15);
    let datasetData = input.data[i].map(point => point.y);
    let isToday = (i === 1 || i === 4);
    let isInjectie = input.series[i].toLowerCase().includes("injectie");
    let pointRadii = [];
    let pointColors = [];

    for (let j = 0; j < TOTAL_POINTS; j++) {
        if (isToday && j === POINTS_PER_DAY + currentQuarter) {
            pointRadii.push(isInjectie ? 3 : 6);
            pointColors.push("rgba(255, 0, 0, 1)");
        } else {
            pointRadii.push(isInjectie ? 1 : 2);
            pointColors.push(colors[i % 3]);
        }
    }

    datasets.push({
        label: input.series[i],
        data: datasetData,
        borderColor: colors[i % 3],
        backgroundColor: pointColors,
        pointRadius: pointRadii,
        fill: false,
        borderDash: isInjectie ? [6, 4] : [],
        borderWidth: isInjectie ? 1 : 2,
        tension: 0.2
    });
}

flow.set("fullPriceArray", data_yesterday.concat(data_today, data_tomorrow));
return { payload: { labels, datasets } };

