    node.warn("Invalid battery power from Modbus: " + JSON.stringify(msg.payload));
    return null; // keep previous good value
}

let P_net_batt_charge = rawPac3;

// Store a recent non-zero value. This protects the dashboard/home calculation
// against occasional SBS read dropouts where the battery value briefly becomes 0.
if (Math.abs(P_net_batt_charge) > 250) {
    flow.set("P_Batt_last_nonzero", P_net_batt_charge);
    flow.set("P_Batt_last_nonzero_seen", Date.now());
}

let U1 = n(flow.get("U1"), 230);
if (U1 < 180 || U1 > 260) U1 = 230;

