}

// Some SMA Modbus values are returned as 1003 = 100.3%.
let soc = raw > 100 ? raw / 10 : raw;

if (!isFinite(soc) || soc < 0 || soc > 100.5) {
    let lastWarn = flow.get('battery_soc_invalid_warn_ts') || 0;
    if (Date.now() - lastWarn > 300000) {
        node.warn('Invalid battery SoC from Modbus, keeping previous good value: ' + JSON.stringify({SoC: raw}));
        flow.set('battery_soc_invalid_warn_ts', Date.now());
    }
    return null;
}

