flow.set("diag_battery_write_ts", now);
flow.set("diag_battery_write_value", watts);
flow.set("diag_battery_write_register", 40149);

// Signed 32-bit conversion to two 16-bit registers.
let value = watts;
if (value < 0) value = 0xFFFFFFFF + value + 1;
let high = (value >>> 16) & 0xFFFF;
let low = value & 0xFFFF;

// Use modbus-flex-write. This avoids the fixed modbus-write response-length issue.
msg.payload = {
    value: [high, low],
    fc: 16,
    unitid: 3,
    address: 40149,
    quantity: 2
};

return msg;

