function regsFromMsg(msg) {
    if (Array.isArray(msg.payload?.data)) return msg.payload.data.map(Number);
    if (Array.isArray(msg.payload)) return msg.payload.map(Number);
    if (Buffer.isBuffer(msg.responseBuffer?.buffer)) {
        const b = msg.responseBuffer.buffer;
        let regs = [];
        for (let i = 0; i + 1 < b.length; i += 2) regs.push(b.readUInt16BE(i));
        return regs;
    }
    if (Buffer.isBuffer(msg.payload?.buffer)) {
        const b = msg.payload.buffer;
        let regs = [];
        for (let i = 0; i + 1 < b.length; i += 2) regs.push(b.readUInt16BE(i));
        return regs;
    }
    return [];
}
function floatBE(regs, i) {
    if (regs.length < i + 2) return 0;
    const b = Buffer.alloc(4);
    b.writeUInt16BE(regs[i] & 0xFFFF, 0);
    b.writeUInt16BE(regs[i+1] & 0xFFFF, 2);
    let v = b.readFloatBE(0);
    return isFinite(v) ? v : 0;
}
let regs = regsFromMsg(msg);
